import{ModalCargoCtrl}from"../../modal/modalCargoCtrl.min.js";class CargoCtrl{static $inject=["$http","modalService","toastService","formulario"];constructor($http,_modalSvc,_toastr,_form){this.$http=$http,this._modalSvc=_modalSvc,this._toastr=_toastr,this._form=_form,this.cargos=[]}$onInit(){this.accion=JSON.parse(localStorage.getItem("accion")),null===this.accion?location.href="/Home/Index":this.accion=this.accion[0],this.initiload()}initiload(){showLoader(),this.$http.get("/Cargo/Get?json="+JSON.stringify({})).then(({data:response})=>{if("0"===response.id)return hideLoader(),void this._toastr.toastr("warning",response.message,response.titleSms);hideLoader(),this.cargos=JSON.parse(response.data)}).catch(error=>{hideLoader(),this._toastr.toastr("error",error)})}async openModal(item){const modalRef=this._modalSvc.openModalSecond(ModalCargoCtrl,"Cargo/_ModalCargo.cshtml","md",item);modalRef.result.then(res=>{"object"==typeof res&&"1"===res.id&&this.initiload()})}async delete(item){let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",html:`<small>Esta seguro de eliminar este Cargo <b>${item.descripcion}</b> ahora?</small>`,confirmButtonText:"Sí, eliminar",showDenyButton:!0,denyButtonText:"No, cancelar",allowOutsideClick:!1});isConfirmed&&this.$http.post("/Cargo/Delete?id="+item.idCargo).then(({data:response})=>{"0"!==response.id?"1"===response.id&&(this._toastr.toastr("success",response.message,response.titleSms),this.initiload()):this._toastr.toastr("warning",response.message,response.titleSms)})}}export default app.controller("cargoCtrl",CargoCtrl);